'use strict';

var Linter = require( 'eslint' ).Linter;
var rule = require( './../lib' );

var linter = new Linter();

var code = 'var arr = new Array( 5 );';

var result = linter.verify( code, {
	'plugins': {
		'stdlib': {
			'rules': {
				'no-new-array': rule
			}
		}
	},
	'rules': {
		'stdlib/no-new-array': 'error'
	}
});
console.log( result );
